export type PlayoffRoundCategory =
  | "First Round"
  | "Conf Semifinals"
  | "Conf Finals"
  | "NBA Finals";

export interface SeriesBoxScoreTotals {
  pts: number;
  reb: number;
  ast: number;
  stl: number;
  blk: number;
  tov: number;
  fgm: number;
  fga: number;
  ftm: number;
  fta: number;
}

export interface PlayoffSeries {
  id?: string;
  season?: string;
  year: number;
  round: "First Round" | "Conference Semifinals" | "Conference Finals" | "NBA Finals";
  roundCategory?: PlayoffRoundCategory;
  roundName?: string;
  roundCode: "EC1" | "WC1" | "ECS" | "WCS" | "ECF" | "WCF" | "FIN";
  opponent: string;
  opponentAbbr: string;
  opponentName?: string;
  franchise: string;
  team: string; // "CLE" | "MIA" | "LAL"
  teamName?: string;
  result: "W" | "L";
  wins: number;
  losses: number;
  games: number;
  gamesWon?: number;
  gamesLost?: number;
  totalGames?: number;
  seriesScore?: string;
  isSweep: boolean;
  sweepType?: "won" | "lost" | null;
  ppg?: number;
  rpg?: number;
  apg?: number;
  spg?: number;
  bpg?: number;
  fgPct?: number;
  threePtPct?: number;
  ftPct?: number;
  boxScoreTotals?: SeriesBoxScoreTotals;
  lebronStats: { ppg: number; rpg: number; apg: number; totalPoints: number };
  signatureMoment: string;
  boxSummary: string;
}

export interface FranchisePostseasonRecord {
  abbr: string;
  name: string;
  seriesPlayed: number;
  seriesWon: number;
  seriesLost: number;
  gamesWon: number;
  gamesLost: number;
  sweepsWon: number;
  sweepsLost: number;
  years: number[];
  seriesList: string[];
}

export interface ChalkboardCoordinates {
  x: number;
  y: number;
  elevation?: number;
}

export interface ChalkboardTelemetry {
  clock: string;
  speed: string;
  distance: string;
  action: string;
}

export interface ChalkboardKeyframe {
  step: number;
  time?: number;
  clock: string;
  description: string;
  annotation?: string;
  lebron: ChalkboardCoordinates;
  ball?: ChalkboardCoordinates;
  defender?: ChalkboardCoordinates;
  passer?: ChalkboardCoordinates;
  inbounder?: ChalkboardCoordinates;
  telemetry?: ChalkboardTelemetry;
}

export interface BuzzerBeaterPlay {
  id: string;
  date: string;
  isoDate?: string;
  season?: string;
  seasonYear: number;
  year?: number;
  opponent: string;
  opponentName?: string;
  round: string;
  roundShort?: string;
  game?: string;
  gameNumber: number;
  team: string;
  venue?: string;
  scoreBefore: string;
  scoreAfter: string;
  result?: string;
  clockRemaining: string;
  shotDistance: string;
  shotType: string;
  courtZone?: string;
  seriesContext: string;
  seriesSituationBefore?: string;
  seriesImpact?: string;
  inbounder: string;
  primaryDefender: string;
  screener?: string;
  broadcastCall: string;
  broadcastCallObj?: { caller: string; network: string; quote: string };
  announcer: string;
  description?: string;
  viewBox: "0 0 500 470" | "0 0 500 940";
  isFullCourt: boolean;
  keyframes: ChalkboardKeyframe[];
}

export type ClutchBuzzerBeater = BuzzerBeaterPlay;

export type TripleDoubleCategory = "Playoffs" | "Regular Season" | "NBA Finals";

export interface TripleDoubleGame {
  id: string;
  date: string;
  season: string;
  year?: number;
  isPlayoff: boolean;
  isFinals: boolean;
  round?: string;
  roundCode?: string;
  gameNumber?: number;
  opponent: string;
  opponentAbbr?: string;
  opponentName?: string;
  franchise: string;
  team: string;
  result: "W" | "L";
  score?: string;
  pts: number;
  reb: number;
  ast: number;
  stl?: number;
  blk?: number;
  minutes?: number;
  venue?: string;
  gameContext: string;
  notes?: string;
  isMonsterGame: boolean;
  monsterTag?: string | null;
  category?: TripleDoubleCategory;
  milestone?: string;
}

export type TripleDoubleEntry = TripleDoubleGame;

export interface TripleDoubleSummary {
  careerTotal: number;
  regularSeasonTotal: number;
  playoffTotal: number;
  finalsTotal: number;
  allThirtyFranchisesBeaten: boolean;
  franchisesConqueredDate: string;
  highestScoringRegularSeason: { pts: number; reb: number; ast: number; opp: string; date: string };
  highestScoringPlayoffs: { pts: number; reb: number; ast: number; opp: string; date: string };
  highestRebounds: { pts: number; reb: number; ast: number; opp: string; date: string };
  highestAssists: { pts: number; reb: number; ast: number; opp: string; date: string };
  oldestAge: string;
  youngestAge: string;
}

